export const comboSong = (shift: number) => {
  const startNote = 8; // G-1

  const notes = [];
  for (let i = 0; i < 3; i++) {
    notes.push(startNote + 2 * i + shift);
  }
  let data = zzfxM(...[[[, 0, 440]], [[[, -1, ...notes]]], [0], 180]);
  zzfxP(...data);
};

